class DataService {
    constructor() {
        this.dataPath = 'data/predictions.json';
    }

    /**
     * Fetches real-time market data generated by GitHub Actions autoupdate workflows.
     * Uses a dynamic timestamp parameter to prevent browser caching.
     */
    async fetchLatestData() {
        try {
            const cacheBuster = new Date().getTime();
            const response = await fetch(`${this.dataPath}?t=${cacheBuster}`);
            
            if (!response.ok) {
                throw new Error(`HTTP error! Status: ${response.status}`);
            }
            
            const data = await response.json();
            return data;
        } catch (error) {
            console.error('Error fetching live stock market data:', error);
            throw error;
        }
    }
}

window.dataService = new DataService();
